/// <summary>
/// Class <c>METProjActualBudgetUIBuilder</c> is a copy of standard report profit and loss actuals vs budget
/// </summary>
internal class METProjActualBudgetUIBuilder extends SrsReportDataContractUIBuilder
{

}

Method.Source:
    public void postBuild()
    {
        boolean projMultContractLinesForProjFeatureEnabled = ProjMultipleContractLinesForProjectFeatureHelper::isFeatureEnabled();

        this.setVisibilityForControls(methodstr(METProjActualBudgetContract, parmTimeMaterial), !projMultContractLinesForProjFeatureEnabled);
        this.setVisibilityForControls(methodstr(METProjActualBudgetContract, parmFixedPrice), !projMultContractLinesForProjFeatureEnabled);
        this.setVisibilityForControls(methodstr(METProjActualBudgetContract, parmInvestment), !projMultContractLinesForProjFeatureEnabled);
        this.setVisibilityForControls(methodstr(METProjActualBudgetContract, parmInternalCost), !projMultContractLinesForProjFeatureEnabled);
        this.setVisibilityForControls(methodstr(METProjActualBudgetContract, parmTime), !projMultContractLinesForProjFeatureEnabled);
        this.setVisibilityForControls(methodstr(METProjActualBudgetContract, parmOnAcc), !projMultContractLinesForProjFeatureEnabled);
        this.setVisibilityForControls(methodstr(METProjActualBudgetContract, parmTimeMaterialBillingMethod), projMultContractLinesForProjFeatureEnabled);
        this.setVisibilityForControls(methodstr(METProjActualBudgetContract, parmFixedPriceBillingMethod), projMultContractLinesForProjFeatureEnabled);
    }

    private void setVisibilityForControls(identifierName methodName, boolean _visible = false)
    {
        DialogField dialogField = this.bindInfo().getDialogField(this.dataContractObject(), methodName);

        if (dialogField)
        {
            dialogField.visible(_visible);
        }
    }
